export function getPostOfficeBn(nameEn?: string | null, code?: string | null): string {
  if (code && POSTCODE_TO_BN[code.trim()]) {
    return POSTCODE_TO_BN[code.trim()];
  }
  if (nameEn) {
    const clean = nameEn.trim().toLowerCase();
    if (POSTOFFICE_EN_TO_BN[clean]) return POSTOFFICE_EN_TO_BN[clean];
  }
  return nameEn || '';
}
